def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        t = op[1]

        # Remove expired entries
        keys_to_remove = []
        for key, (value, write_time) in cache.items():
            if write_time + ttl <= t:
                keys_to_remove.append(key)
        for key in keys_to_remove:
            del cache[key]

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # If key exists, remove it first (to re-add at the end)
            if key in cache:
                del cache[key]
            # If cache is full and key is new, evict LRU
            elif len(cache) >= capacity:
                # Remove the first item (least recently used)
                cache.popitem(last=False)

            # Add the entry as most recently used
            cache[key] = (value, t)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Move to end (make most recently used)
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

